beforeExample:
public class MyClass {
    public void process() {
        String emptyString = new java.lang.String();
        System.out.println(emptyString.length());
    }
}

afterExample:
public class MyClass {
    public void process() {
        String emptyString = "";
        System.out.println(emptyString.length());
    }
}

negativeExample:
public class MyClass {
    public void process() {
        String non_empty = new java.lang.String("hello"); // Should not match
        byte[] bytes = { 'a', 'b', 'c' };
        String from_bytes = new java.lang.String(bytes); // Should not match
        System.out.println(non_empty + from_bytes);
    }
}
